head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > openPopup]<br/>지정한 옵션에 맞게 팝업을 생성하여 엽니다.",
    "validation" : [
        "options.modal(선택) 파라미터를 true 로 설정하면, 팝업을 호출한 부모 창을 컨트롤 할 수 없습니다.",
        "options.modal(선택) 파라미터를 false 로 설정하면, 팝업을 호출한 부모 창을 컨트롤 할 수 있습니다.",
        "options.modal(선택) 파라미터 생략 시, 기본값 false 로 동작합니다.",
        "options.left(선택) 파라미터로 팝업의 좌측(Left) 위치를 설정합니다.",
        "options.left(선택) 파라미터는 options.type 속성값이 'browserPopup' 이 아닌 경우 웹브라우저를 기준으로 계산합니다.",
        "options.left(선택) 파라미터는 options.type 속성값이 'browserPopup' 인 경우 모니터를 기준으로 계산합니다.",
        "options.left(선택) 파라미터 생략 시, 기본값 '100px' 로 동작합니다.",
        "options.top(선택) 파라미터로 팝업의 상단(Top) 위치를 설정합니다.",
        "options.top(선택) 파라미터는 options.type 속성값이 'browserPopup' 이 아닌 경우 웹브라우저를 기준으로 계산합니다.",
        "options.top(선택) 파라미터는 options.type 속성값이 'browserPopup' 인 경우 모니터를 기준으로 계산합니다.",
        "options.top(선택) 파라미터 생략 시, 기본값 '100px' 로 동작합니다.",
        "options.width(선택) 파라미터로 팝업의 너비(Width)를 설정합니다.",
        "options.width(선택) 파라미터 생략 시, 기본값 '500px' 로 동작합니다.",
        "options.height(선택) 파라미터로 팝업의 높이(Height)를 설정합니다.",
        "options.height(선택) 파라미터 생략 시, 기본값 '500px' 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    $c.gcm.createLabel('label="[확인] modal=true 이면 팝업이 열린 동안 부모 화면의 버튼·입력 영역이 조작되지 않는지 직접 클릭해 확인합니다.\n[확인] browserPopup 은 모니터 좌상단 기준 창 위치(screenX, screenY)로 출력합니다."', '', 'label1');

    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.popupUrl = "/sample/common_link/p_openPopup_popup.xml";



scwin.out = function (str) {
    wf_body_bottom.getObj("scwin").setReturnValue(str);
};



// 이전 테스트 팝업 정리 (내부 팝업을 정리했으면 true 반환)
scwin.closeAllPopup = function () {
    let list = $p.getAllPopupList().slice();
    let closedInner = false;
    for (let i = 0; i < list.length; i++) {
        let pw = list[i].popupWin;
        try {
            if (pw && typeof pw.forceClose === "function") {
                pw.forceClose();
                closedInner = true;
            } else if (pw && typeof pw.close === "function") {
                pw.close();
            }
        } catch (e) {}
    }
    return closedInner;
};



// 이전 팝업 정리 후 openPopup 실행
// (내부 팝업 정리는 비동기로 끝나므로 300ms 후 연다. 클릭 직후 5초 이내라 browserPopup 도 사용자 동작으로 처리됨)
scwin.runOpenPopup = function (optionList, callback, delay) {
    let fn = function () {
        for (let i = 0; i < optionList.length; i++) {
            $p.openPopup(scwin.popupUrl, optionList[i]);
        }
        if (callback) setTimeout(callback, delay || 1500);
    };
    if (scwin.closeAllPopup()) {
        setTimeout(fn, 300);
    } else {
        fn();
    }
};



// options.id 로 팝업 정보 조회 (Page Scope 적용 시 실행 ID 는 'mf_' 접두사가 붙음)
scwin.findPopup = function (id) {
    let list = $p.getAllPopupList();
    for (let i = list.length - 1; i >= 0; i--) {
        if ((list[i].options.org_id === id || list[i].options.id === id) && list[i].popupWin) return list[i];
    }
    return null;
};



// options.id 로 팝업 최상위 div 조회
scwin.popupEl = function (id) {
    return document.querySelector(".w2popup_window[id$='" + id + "']");
};



// 팝업 내부 요소(타이틀바 버튼 등) 조회
scwin.popupPart = function (id, suffix) {
    let el = scwin.popupEl(id);
    return el ? document.getElementById(el.id + "_" + suffix) : null;
};



scwin.rectStr = function (el) {
    let r = el.getBoundingClientRect();
    return "left " + Math.round(r.left + window.scrollX) + ", top " + Math.round(r.top + window.scrollY) + " / 크기 : " + Math.round(r.width) + " x " + Math.round(r.height);
};

scwin.btn_openPopup_onclick = function () {
    let type = par_type.getValue();
    let modal = par_modal.getValue();
    let position = par_position.getValue();
    let size = par_size.getValue();

    let options = { id: "popup_1", type: type, popupName: "openPopup 팝업" };
    if (modal !== "") options.modal = (modal === "true");
    if (position === "set") {
        options.left = "250px";
        options.top = "150px";
    }
    if (size === "set") {
        options.width = "400px";
        options.height = "280px";
    }

    scwin.runOpenPopup([options], scwin.printResult);
};



// validation 1~15 판정 출력 (위치 / 크기 / 부모 창 modal 레이어)
scwin.printResult = function () {
    let pw = scwin.findPopup("popup_1");
    if (!pw) {
        scwin.out("팝업 생성 : false");
        return;
    }
    let modalEl = document.getElementById("_modal");
    let isModal = !!modalEl && window.getComputedStyle(modalEl).display !== "none";
    if (pw.options.type === "browser") {
        let w = pw.popupWin;
        scwin.out("모니터 기준 위치 : screenX " + w.screenX + ", screenY " + w.screenY + " / 크기 : " + w.innerWidth + " x " + w.innerHeight + " / 부모 창 modal 레이어 : " + isModal);
    } else {
        let el = scwin.popupEl("popup_1");
        scwin.out("웹브라우저 기준 위치 : " + scwin.rectStr(el) + " / 부모 창 modal 레이어 : " + isModal);
    }
};
